import { readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { fixture } from "./fixture.ts";

const out = process.argv[2] ?? join(homedir(), ".config", "cmux", "sidebars", "dashboard-preview.js");
const dashboard = readFileSync(new URL("../dist/dashboard.js", import.meta.url), "utf8");
const mock = JSON.stringify(fixture);

// Parameters shadow cmux's `data` and `cmux` globals, so the real dashboard draws the fixture
// with a frozen clock and its taps go nowhere.
writeFileSync(
  out,
  [
    "// Generated by preview/build.ts: dist/dashboard.js drawing preview/fixture.ts. Do not edit.",
    `const MOCK = ${mock};`,
    "((data, cmux) => {",
    dashboard,
    "})({ workspaces: () => MOCK.workspaces, groups: () => MOCK.groups, clock: () => MOCK.clock }, () => {});",
    "",
  ].join("\n"),
);
console.log(`Wrote ${out}`);
